 "content": "def transform(grid):
    out = [row[:] for row in grid]
    h, w = len(grid), len(grid[0])
    blocks = []
    for r in range(h - 1):
        for c in range(w - 1):
            if all(grid[rr][cc] == 2 for rr, cc in ((r,c),(r,c+1),(r+1,c),(r+1,c+1))):
                blocks.append((r,c))
    for r, c in blocks:
        # Corner markers around a 2x2 block, rotate their colors clockwise.
        ul = grid[r-1][c-1] if r > 0 and c > 0 else 0
        ur = grid[r-1][c+2] if r > 0 and c+2 < w else 0
        ll = grid[r+2][c-1] if r+2 < h and c > 0 else 0
        lr = grid[r+2][c+2] if r+2 < h and c+2 < w else 0
        rays = [
            (r-1, c-1, -1, -1, ll),
            (r-1, c+2, -1,  1, ul),
            (r+2, c-1,  1, -1, lr),
            (r+2, c+2,  1,  1, ur),
        ]
        for sr, sc, dr, dc, color in rays:
            if color == 0 or not (0 <= sr < h and 0 <= sc < w):
                continue
            rr, cc = sr, sc
            while 0 <= rr < h and 0 <= cc < w:
                out[rr][cc] = color
                rr += dr
                cc += dc
    return out
